// ─── File: src/main/java/com/bank/exception/exception/GlobalExceptionHandler.java ───
// MODERN PATTERN: handle unchecked exceptions globally — one place!
package com.bank.exception.exception;

import com.bank.exception.dto.ErrorResponse;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(InsufficientBalanceException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ErrorResponse handleInsufficientBalance(InsufficientBalanceException e) {
        return new ErrorResponse("INSUFFICIENT_BALANCE", e.getMessage(), "amount");
    }

    @ExceptionHandler(TradeValidationException.class)
    @ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
    public ErrorResponse handleValidation(TradeValidationException e) {
        return new ErrorResponse("VALIDATION_ERROR", e.getMessage(), e.getField());
    }

    @ExceptionHandler(RuntimeException.class)
    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public ErrorResponse handleGeneric(RuntimeException e) {
        return new ErrorResponse("INTERNAL_ERROR", "Unexpected error: " + e.getMessage(), null);
    }
}
// ALL unchecked exceptions handled in ONE class! No per-method try-catch!
```

