// ─── File: src/main/java/com/bank/exception/service/TradeProcessingService.java ───
package com.bank.exception.service;

import com.bank.exception.exception.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.nio.file.*;

@Service
@Slf4j
public class TradeProcessingService {

    // ═══ CHECKED: caller MUST handle (try-catch or throws) ═══
    public String readTradeFile(String path) throws TradeFileNotFoundException {
        try {
            return Files.readString(Path.of(path));
        } catch (java.io.IOException e) {
            throw new TradeFileNotFoundException("Trade file not found: " + path, e);
            // Wraps IOException (checked) in our custom checked exception
        }
    }

    // ═══ CHECKED with recovery: try primary, fallback to backup ═══
    public String readTradeFileWithFallback(String primary, String backup) {
        try {
            return readTradeFile(primary);  // try primary
        } catch (TradeFileNotFoundException e) {
            log.warn("Primary file not found, trying backup: {}", e.getMessage());
            try {
                return readTradeFile(backup);  // try backup — recovery!
            } catch (TradeFileNotFoundException e2) {
                throw new RuntimeException("Both primary and backup files missing!", e2);
            }
        }
    }

    // ═══ UNCHECKED: programming bug — caller should validate first ═══
    public void withdraw(BigDecimal balance, BigDecimal amount) {
        if (balance.compareTo(amount) < 0) {
            throw new InsufficientBalanceException(balance, amount);
            // No "throws" in signature! Unchecked — RuntimeException.
        }
        log.info("Withdrawn Rs.{}, remaining Rs.{}", amount, balance.subtract(amount));
    }

    // ═══ UNCHECKED: business validation — global handler catches ═══
    public void validateTrade(String symbol, BigDecimal amount) {
        if (symbol == null || symbol.isBlank()) {
            throw new TradeValidationException("symbol", "Symbol is required");
        }
        if (amount == null || amount.signum() <= 0) {
            throw new TradeValidationException("amount", "Amount must be positive");
        }
    }
}
```

