// ─── File: src/main/java/com/bank/throwdemo/service/TradeService.java ───
package com.bank.throwdemo.service;

import com.bank.throwdemo.exception.TradeFileException;
import java.math.BigDecimal;
import java.nio.file.*;

public class TradeService {

    // ═══ throw ONLY (unchecked — no throws needed in signature) ═══
    public void withdraw(BigDecimal balance, BigDecimal amount) {
        if (amount.signum() <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
            // throw = CREATES exception + THROWS it NOW
            // No "throws" in method signature — unchecked!
        }
        if (balance.compareTo(amount) < 0) {
            throw new RuntimeException("Insufficient balance: " + balance + " < " + amount);
        }
    }

    // ═══ BOTH throw AND throws (checked exception) ═══
    public String readTradeFile(String path) throws TradeFileException {
        //                                   ^^^^^^^^^^^^^^^^^^^^^^ DECLARES: might throw
        try {
            return Files.readString(Path.of(path));
        } catch (java.io.IOException e) {
            throw new TradeFileException("Cannot read: " + path, e);
            // ^^^^^ CREATES + THROWS checked exception
        }
    }

    // ═══ throws MULTIPLE exceptions ═══
    public void processAndStore(String filePath) throws TradeFileException, IllegalStateException {
        //                                        ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
        //                                        Two exceptions declared
        String data = readTradeFile(filePath);  // might throw TradeFileException
        if (data.isBlank()) {
            throw new IllegalStateException("Empty file!");  // unchecked — throws optional but documented
        }
    }

    // ═══ Re-throw pattern ═══
    public void validateAndProcess(BigDecimal amount) {
        try {
            withdraw(BigDecimal.ZERO, amount);
        } catch (RuntimeException e) {
            // Log, then re-throw:
            System.err.println("Validation failed: " + e.getMessage());
            throw e;  // RE-THROW the same exception — no "new"
        }
    }
}
```

