// ─── File: src/main/java/com/bank/finallydemo/service/FinallyDemoService.java ───
package com.bank.finallydemo.service;

import java.util.ArrayList;
import java.util.List;

public class FinallyDemoService {

    private final List<String> executionLog = new ArrayList<>();

    // ═══ finally after normal execution ═══
    public String normalFlow() {
        try {
            executionLog.add("TRY");
            return "success";
        } finally {
            executionLog.add("FINALLY");
            // Runs AFTER try, BEFORE return is delivered to caller
        }
    }

    // ═══ finally after exception ═══
    public String exceptionFlow() {
        try {
            executionLog.add("TRY");
            throw new RuntimeException("oops");
        } catch (RuntimeException e) {
            executionLog.add("CATCH");
            return "caught";
        } finally {
            executionLog.add("FINALLY");
            // Runs AFTER catch, BEFORE return is delivered
        }
    }

    // ═══ finally after unhandled exception ═══
    public void unhandledFlow() {
