```java
// ═══ HIERARCHY ═══
// Throwable
//   ├── Error                ← JVM-level, unchecked, DON'T catch
//   │     ├── OutOfMemoryError
//   │     ├── StackOverflowError
//   │     ├── VirtualMachineError
//   │     ├── NoClassDefFoundError
//   │     └── ExceptionInInitializerError
//   └── Exception             ← Application-level, catch and handle
//         ├── IOException     (checked)
//         ├── SQLException    (checked)
//         └── RuntimeException (unchecked)
//               ├── NullPointerException
//               └── IllegalArgumentException

// ═══ ERROR: JVM is broken — don't catch ═══
// OutOfMemoryError: heap full — no more objects can be created
// StackOverflowError: call stack too deep (infinite recursion)
// NoClassDefFoundError: class was available at compile time but missing at runtime

public void causeOOM() {
    List<byte[]> list = new ArrayList<>();
    while (true) {
        list.add(new byte[1024 * 1024]);  // allocate 1MB until OOM!
    }
    // → OutOfMemoryError: Java heap space
    // JVM can't allocate memory. Catching this is MEANINGLESS — you can't create
    // new objects to "handle" it because there's no memory left!
}

public void causeStackOverflow() {
    causeStackOverflow();  // infinite recursion
    // → StackOverflowError: each call adds a frame to the stack until it's full
}

// ═══ EXCEPTION: application handles it ═══
public void handleException() {
    try {
        String data = Files.readString(Path.of("/trades.csv"));
    } catch (IOException e) {
        // Recoverable! Try another path, use default data, alert ops team.
        log.error("File read failed, using fallback", e);
    }
}
