    void error_isUnchecked() {
        assertThat(Throwable.class.isAssignableFrom(Error.class)).isTrue();
        assertThat(Exception.class.isAssignableFrom(Error.class)).isFalse();
        // Error extends Throwable, NOT Exception!
    }

    @Test
    void stackOverflow_isAnError() {
        assertThatThrownBy(() -> service.infiniteRecursion(0))
            .isInstanceOf(StackOverflowError.class);
        // StackOverflowError extends Error — JVM problem!
    }

    @Test
    void arithmeticException_isAnException() {
        assertThatThrownBy(() -> service.safeDivide(10, 0))
            .isInstanceOf(ArithmeticException.class);
        // ArithmeticException extends RuntimeException extends Exception
    }

    @Test
    void badCatchAll_swallowsError() {
        String result = service.badCatchAll(() -> service.infiniteRecursion(0));
        assertThat(result).isEqualTo("swallowed: StackOverflowError");
        // ❌ Error was SWALLOWED! JVM problem hidden. Processing continues in bad state!
    }

    @Test
    void goodCatch_letsErrorPropagate() {
        assertThatThrownBy(() -> service.goodCatch(() -> service.infiniteRecursion(0)))
            .isInstanceOf(StackOverflowError.class);
        // ✅ Error PROPAGATES! JVM crashes cleanly. No corrupted state.
    }

    @Test
    void goodCatch_handlesException() {
        String result = service.goodCatch(() -> service.safeDivide(10, 0));
        assertThat(result).isEqualTo("handled: ArithmeticException");
        // ✅ Exception caught and handled. Error would propagate.
    }

    @Test
    void hierarchy() {
        // Error: NOT recoverable. Don't catch.
        assertThat(Error.class.getSuperclass()).isEqualTo(Throwable.class);
        // Exception: recoverable. Catch and handle.
        assertThat(Exception.class.getSuperclass()).isEqualTo(Throwable.class);
        // RuntimeException: unchecked Exception.
        assertThat(RuntimeException.class.getSuperclass()).isEqualTo(Exception.class);
    }
