// ═══ WITHOUT chaining: low-level exception LEAKS to caller ═══
public class TradeService {
    public void settleTrade(String tradeId) throws SQLException {
        //                                        ^^^^^^^^^^^ LEAKED!
        // Controller now depends on java.sql — implementation detail!
        // If we switch to MongoDB → method signature CHANGES → all callers break!
        jdbc.execute("UPDATE trades SET status='SETTLED' WHERE id=?", tradeId);
    }
}

// ═══ WITH chaining: domain exception wraps cause ═══
public class TradeService {
    public void settleTrade(String tradeId) {
        try {
            jdbc.execute("UPDATE trades SET status='SETTLED' WHERE id=?", tradeId);
        } catch (SQLException e) {
            throw new TradeSettlementException(
                "Settlement failed for trade " + tradeId, e);
            //    domain-meaningful message ↑         ↑ original cause preserved!
        }
    }
}
// Controller: catches TradeSettlementException — doesn't know about SQL!
// Stack trace: TradeSettlementException: Settlement failed for TRD-001
//              Caused by: java.sql.SQLException: Connection refused: localhost:5432
// BOTH the business context AND the technical root cause are visible!

// ═══ getCause() — retrieve original ═══
try {
    tradeService.settleTrade("TRD-001");
} catch (TradeSettlementException e) {
    log.error("Trade error: {}", e.getMessage());        // domain message
    log.error("Root cause: {}", e.getCause().getMessage()); // SQL error
    // e.getCause() → SQLException
    // e.getCause().getCause() → possible deeper cause (network error?)
}

// ═══ Custom domain exception with cause constructor ═══
public class TradeSettlementException extends RuntimeException {
    private final String tradeId;

    public TradeSettlementException(String message, Throwable cause) {
        super(message, cause);  // passes cause to Throwable — creates the chain!
        this.tradeId = extractTradeId(message);
    }

    public TradeSettlementException(String message) {
        super(message);  // no cause — standalone exception
        this.tradeId = extractTradeId(message);
    }

    public String getTradeId() { return tradeId; }

    private String extractTradeId(String msg) {
        // extract from message or pass separately
        return msg.contains("TRD-") ? msg.substring(msg.indexOf("TRD-"), msg.indexOf("TRD-") + 7) : "UNKNOWN";
    }
}

// ═══ MULTI-LEVEL chaining ═══
// Network → SQL → Repository → Service → Controller
// SocketException: Connection refused
//   → SQLException: Unable to get connection
//     → DataAccessException: Query failed
//       → TradeSettlementException: Settlement failed for TRD-001
// Each level adds CONTEXT. getCause() chain preserves ALL levels.
```

