// ═══ GLOBAL EXCEPTION HANDLER — ONE class handles ALL exceptions ═══
@RestControllerAdvice
public class GlobalExceptionHandler {

    // Handle business error: 400 Bad Request
    @ExceptionHandler(InsufficientBalanceException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ErrorResponse handleInsufficientBalance(InsufficientBalanceException e) {
        return new ErrorResponse("INSUFFICIENT_BALANCE", e.getMessage(), HttpStatus.BAD_REQUEST.value());
    }

    // Handle not found: 404
    @ExceptionHandler(TradeNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public ErrorResponse handleNotFound(TradeNotFoundException e) {
        return new ErrorResponse("NOT_FOUND", e.getMessage(), 404);
    }

    // Handle validation: 422
    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
    public ErrorResponse handleValidation(MethodArgumentNotValidException e) {
        String field = e.getBindingResult().getFieldErrors().stream()
            .map(f -> f.getField() + ": " + f.getDefaultMessage())
            .collect(Collectors.joining(", "));
        return new ErrorResponse("VALIDATION_ERROR", field, 422);
    }

    // Handle everything else: 500
    @ExceptionHandler(Exception.class)
    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public ErrorResponse handleGeneric(Exception e) {
        log.error("Unhandled exception", e);  // log full stack trace!
        return new ErrorResponse("INTERNAL_ERROR", "Something went wrong", 500);
        // DON'T expose internal details to client!
    }
}

// ═══ CONTROLLER: ZERO try-catch! ═══
@RestController
@RequestMapping("/api/v1/trades")
