// ─── File: src/main/java/com/bank/multicatch/service/FileProcessorService.java ───
package com.bank.multicatch.service;

import java.io.FileNotFoundException;
import java.io.IOException;
import java.sql.SQLException;

public class FileProcessorService {

    public String processFile(String path) throws IOException, SQLException {
        if (path.contains("notfound")) throw new FileNotFoundException("File: " + path);
        if (path.contains("ioerror")) throw new IOException("IO error: " + path);
        if (path.contains("sqlerror")) throw new SQLException("DB error for: " + path);
        if (path.contains("nullbug")) throw new NullPointerException("null in: " + path);
        return "Processed: " + path;
    }

    // ═══ CORRECT ordering: specific → general ═══
    public String processWithCorrectOrder(String path) {
        try {
            return processFile(path);
        } catch (FileNotFoundException e) {
            return "CATCH-1 (FileNotFound): " + e.getMessage();  // most specific
        } catch (IOException e) {
            return "CATCH-2 (IOException): " + e.getMessage();   // less specific
        } catch (SQLException e) {
            return "CATCH-3 (SQLException): " + e.getMessage();  // unrelated to IO
        } catch (RuntimeException e) {
            return "CATCH-4 (Runtime): " + e.getMessage();       // unchecked
        }
    }

    // ═══ MULTI-CATCH: one block for unrelated exceptions ═══
    public String processWithMultiCatch(String path) {
        try {
            return processFile(path);
        } catch (IOException | SQLException e) {
            // ONE block handles both IO and SQL errors!
            return "MULTI-CATCH (IO|SQL): " + e.getMessage();
            // e is final — can't reassign
        } catch (RuntimeException e) {
            return "RUNTIME: " + e.getMessage();
        }
    }
}
