// ═══ HOW fillInStackTrace WORKS ═══
// Every "new Exception()" internally calls:
public synchronized Throwable fillInStackTrace() {
    // Native method: walks the JVM stack frame by frame
    // Creates StackTraceElement[] with: class, method, file, line for each frame
    // For 20-frame deep stack: 20 StackTraceElement objects created
    // Takes: ~1-5 microseconds (native call + object allocation)
}

// ═══ THE COST ═══
// 1 exception: ~2μs — negligible
// 10,000 exceptions/second: ~20ms of CPU per second — 2% overhead!
// 100,000 exceptions/second: ~200ms — 20% overhead! Performance killer!

// ═══ STACKLESS EXCEPTION — override fillInStackTrace ═══
public class ValidationException extends RuntimeException {

    // Override: return 'this' WITHOUT capturing stack trace
    @Override
    public synchronized Throwable fillInStackTrace() {
        return this;  // NO stack capture! ~100x faster to create!
    }

    // Use a SINGLETON for even more efficiency:
    public static final ValidationException INVALID_AMOUNT =
        new ValidationException("Amount must be positive");
    // Created ONCE, thrown many times. Zero allocation per throw!

    public ValidationException(String message) { super(message); }
}

// ═══ WHEN TO USE STACKLESS ═══
// HOT PATH: thrown 10K+ times per second
// KNOWN THROW POINT: you know exactly where it's thrown (no need to trace)
// CONTROL FLOW: used for expected business logic, not debugging
// Example: cache miss → throw CacheMissException (stackless) → retry from DB

// ═══ WHEN TO KEEP STACK TRACE ═══
// RARE: thrown occasionally (real errors)
// DEBUGGING: need to know WHERE it happened (line numbers)
// UNEXPECTED: NullPointer, ClassCast — need the full trace!
```

