        if (tradeId == null || tradeId.isBlank()) {
            throw new IllegalArgumentException("tradeId required");
        }

        BigDecimal amount = repo.findById(tradeId)
            .orElseThrow(() -> new TradeNotFoundException(tradeId));
        // Fails HERE with clear "Trade not found: TRD-999" — not 5 layers deep!

        if (amount.compareTo(MAX_MARGIN) > 0) {
            throw new InsufficientMarginException(amount, MAX_MARGIN);
        }

        // ═══ NO catch here! Exceptions propagate to controller/boundary ═══
        return "SETTLED: " + tradeId + " Rs." + amount;
    }
