// ═══ FIX: LAZY INITIALIZATION ═══
public class DatabasePool {
    private static volatile DataSource ds;  // not initialized at class load!

    public static DataSource getDataSource() {
        if (ds == null) {
            synchronized (DatabasePool.class) {
                if (ds == null) {
                    ds = createPool();  // initialized on FIRST USE, not class load
                    // If it fails: method throws exception, but class is NOT dead!
                    // Next call can retry!
                }
            }
        }
        return ds;
    }
}
