public class TradingSession {
    private boolean open = false;

    public void open() { this.open = true; }
    public void close() { this.open = false; }

    public void executeTrade(Trade trade) {
        if (!open)
            throw new IllegalStateException("Trading session is CLOSED — call open() first");
        // Arguments are fine! But the session is in wrong state.
        // Caller's timing is wrong, not their input.
        process(trade);
