public void transfer(String from, String to, BigDecimal amount) {
    checkArgument(from != null && !from.isBlank(), "from required");     // → IAE
    checkArgument(amount.signum() > 0, "amount must be positive: %s", amount); // → IAE
    checkState(isConnected(), "Service not connected — call connect() first"); // → ISE
}

// ═══ DECISION GUIDE ═══
// Q: "Would this method work if the caller passed DIFFERENT arguments?"
//    YES → IllegalStateException (state is wrong, not input)
//    NO  → IllegalArgumentException (input is wrong)
//
// Q: "Is the problem with WHAT was passed or WHEN it was called?"
//    WHAT → IAE    WHEN → ISE
