package com.bank.iaevise;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.Objects;
import static org.assertj.core.api.Assertions.*;

class IAEvsISETest {

    // ═══ Trading session: demonstrates both IAE and ISE ═══
    static class TradingSession {
        private boolean open = false;

        void open() { open = true; }
        void close() { open = false; }

        String executeTrade(String symbol, BigDecimal amount) {
            // IAE: bad arguments
            if (symbol == null || symbol.isBlank())
                throw new IllegalArgumentException("symbol required");
            if (amount == null || amount.signum() <= 0)
                throw new IllegalArgumentException("amount must be positive");

            // ISE: wrong state
            if (!open)
                throw new IllegalStateException("Session closed — call open() first");

            return "EXECUTED: " + symbol + " Rs." + amount;
        }
    }

    @Test
    void iae_badSymbol() {
        TradingSession session = new TradingSession();
        session.open();
        assertThatThrownBy(() -> session.executeTrade("", new BigDecimal("1000")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("symbol");
    }

    @Test
    void iae_negativeAmount() {
        TradingSession session = new TradingSession();
        session.open();
        assertThatThrownBy(() -> session.executeTrade("RELIANCE", new BigDecimal("-500")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("positive");
    }

    @Test
    void ise_sessionClosed() {
        TradingSession session = new TradingSession();
        // NOT opened! State is wrong.
        assertThatThrownBy(() -> session.executeTrade("RELIANCE", new BigDecimal("1000")))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("closed");
    }

    @Test
    void success_validInputAndState() {
        TradingSession session = new TradingSession();
        session.open();
        String result = session.executeTrade("TCS", new BigDecimal("5000"));
        assertThat(result).contains("TCS").contains("5000");
    }

    @Test
    void requireNonNull_throwsNPE() {
        assertThatThrownBy(() -> Objects.requireNonNull(null, "trade must not be null"))
            .isInstanceOf(NullPointerException.class)
            .hasMessage("trade must not be null");
        // Objects.requireNonNull throws NPE, NOT IAE — by design.
    }

    // ═══ ISE: already settled (idempotency violation) ═══
    static class Trade {
        private boolean settled = false;
        void settle() {
            if (settled) throw new IllegalStateException("Trade already settled");
            settled = true;
        }
    }

    @Test
    void ise_alreadySettled() {
        Trade trade = new Trade();
        trade.settle();  // first time: OK
        assertThatThrownBy(trade::settle)  // second time: ISE!
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("already settled");
    }
}
