// ═══ JAVA SOURCE ═══
public String process(String tradeId) {
    try {
        return settle(tradeId);        // normal path
    } catch (IOException e) {
        return "IO_ERROR";             // handler 1
    } catch (SQLException e) {
        return "SQL_ERROR";            // handler 2
    }
}

// ═══ BYTECODE EXCEPTION TABLE (javap -c -v) ═══
// Exception table:
//   from    to    target  type
//     0     10      13    Class java/io/IOException
//     0     10      20    Class java/sql/SQLException
//
// Translation:
// If exception thrown between PC 0-10 (the try body):
//   If exception IS-A IOException  → jump to PC 13 (catch block 1)
//   If exception IS-A SQLException → jump to PC 20 (catch block 2)
//   If neither matches             → pop frame, check caller's table

// ═══ WHY ZERO COST ON HAPPY PATH ═══
// The try body (PC 0-10) is PLAIN bytecode — no extra instructions!
// No: if (exceptionOccurred) goto handler;
// No: push/pop try markers
// No: register/unregister handlers
// Just: the normal code runs. Table is metadata, not executable code.
//
// Cost appears ONLY when exception thrown:
// 1. fillInStackTrace() — walk stack, create StackTraceElement[] (~2μs)
// 2. Table lookup — find matching handler (fast — small table)
// 3. Stack unwinding — pop frames until handler found
// Total: ~5-50μs per thrown exception (depends on stack depth)

// ═══ VERIFY WITH javap ═══
// javap -c -v MyClass.class
// Shows the exception table for each method
