// ═══ COST BREAKDOWN ═══
throw new RuntimeException("msg");
// Step 1: new RuntimeException() → constructor calls fillInStackTrace()
//   → native method walks thread stack (20 frames = 20 StackTraceElements)
//   → allocates StackTraceElement[] array
//   → ~1-5 microseconds
// Step 2: throw → JVM begins stack unwinding
//   → pops current frame, checks exception table
//   → pops next frame, checks exception table
//   → repeats until handler found (or thread dies)
//   → ~0.5-2 microseconds
// Step 3: handler found → jumps to catch block
// TOTAL: ~2-7 microseconds per throw

// Normal return: ~0.01 microseconds (10-700x cheaper!)

// ═══ OPTIMIZATION 1: STACKLESS (override fillInStackTrace) ═══
public class FastValidationException extends RuntimeException {
    @Override public synchronized Throwable fillInStackTrace() {
        return this;  // skip stack capture!
    }
    // Cost: ~0.02μs (100x cheaper than normal exception)
}

// ═══ OPTIMIZATION 2: PRE-BUILT SINGLETON ═══
public class CacheMissException extends RuntimeException {
    public static final CacheMissException INSTANCE = new CacheMissException();
    private CacheMissException() { super("cache miss"); }
    @Override public synchronized Throwable fillInStackTrace() { return this; }
    // Zero allocation per throw! Created once, reused forever.
}
// Usage: throw CacheMissException.INSTANCE;

// ═══ OPTIMIZATION 3: AVOID EXCEPTIONS FOR EXPECTED CASES ═══

// ❌ SLOW: exception for expected case
public Account findAccount(String id) {
    Account acc = cache.get(id);
    if (acc == null) throw new AccountNotFoundException(id);  // 10K times/sec!
    return acc;
}

// ✅ FAST: Optional for expected case
public Optional<Account> findAccount(String id) {
    return Optional.ofNullable(cache.get(id));  // no exception!
}

// ❌ SLOW: parseInt with exception
boolean isNumeric(String s) {
    try { Integer.parseInt(s); return true; }
    catch (NumberFormatException e) { return false; }  // exception for normal flow!
}

// ✅ FAST: check without exception
