package com.bank.cost;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ExceptionCostTest {

    // Normal exception (with stack trace)
    static class NormalEx extends RuntimeException {
        NormalEx(String msg) { super(msg); }
    }

    // Stackless exception (no stack trace)
    static class StacklessEx extends RuntimeException {
        static final StacklessEx INSTANCE = new StacklessEx("validation failed");
        StacklessEx(String msg) { super(msg); }
        @Override public synchronized Throwable fillInStackTrace() { return this; }
    }

    // Return-code pattern (no exception at all)
    record ValidationResult(boolean valid, String error) {
        static ValidationResult ok() { return new ValidationResult(true, null); }
        static ValidationResult fail(String error) { return new ValidationResult(false, error); }
    }

    @Test
    void costComparison() {
        int iterations = 100_000;

        // 1. Normal exception (expensive):
        long t1 = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            try { throw new NormalEx("fail"); } catch (NormalEx e) { }
        }
        long normalMs = (System.nanoTime() - t1) / 1_000_000;

        // 2. Stackless singleton (cheap):
        long t2 = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            try { throw StacklessEx.INSTANCE; } catch (StacklessEx e) { }
        }
        long stacklessMs = (System.nanoTime() - t2) / 1_000_000;

        // 3. Return code (cheapest):
        long t3 = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            ValidationResult r = ValidationResult.fail("fail");
            if (!r.valid()) { /* handle */ }
        }
        long returnMs = (System.nanoTime() - t3) / 1_000_000;

        System.out.println("Normal: " + normalMs + "ms | Stackless: " + stacklessMs + "ms | Return: " + returnMs + "ms");
        // Typical: Normal ~150ms | Stackless ~3ms | Return ~1ms
        assertThat(stacklessMs).isLessThan(normalMs);
        assertThat(returnMs).isLessThanOrEqualTo(stacklessMs);
    }

    @Test
    void stacklessHasNoTrace() {
        try {
            throw StacklessEx.INSTANCE;
        } catch (StacklessEx e) {
            assertThat(e.getStackTrace()).isEmpty();
            assertThat(e.getMessage()).isEqualTo("validation failed");
        }
    }

    @Test
    void returnCode_noExceptionOverhead() {
        ValidationResult result = ValidationResult.fail("Amount negative");
        assertThat(result.valid()).isFalse();
        assertThat(result.error()).isEqualTo("Amount negative");
        // Zero exception overhead. Just a record object.
    }
}
